const input=$input.first().json.body||$input.first().json;
const u=input.underwriting_pipeline||input.underwriting||input;
const n=v=>{const x=Number(v);return Number.isFinite(x)?x:null};
const arv=n(input.arv??u.arv??u.after_repair_value);
const repairs=n(input.repair_estimate??u.repair_estimate??u.repairs);
const holding=n(input.holding_costs??u.holding_costs);
const closing=n(input.closing_costs??u.closing_costs);
const assignment=n(input.assignment_fee??u.assignment_fee);
const maoPct=n(input.mao_percentage??u.mao_percentage);
const providedMao=n(input.mao??u.mao??u.maximum_allowable_offer);
const missing=[];
for(const [k,v] of Object.entries({arv,repairs,holding,closing,assignment})){if(v===null)missing.push(k)}
if(maoPct===null&&providedMao===null)missing.push('mao_percentage_or_mao');
const mao=providedMao!==null?providedMao:(arv!==null&&maoPct!==null?arv*maoPct-(repairs||0)-(holding||0)-(closing||0)-(assignment||0):null);
const evidenceCount=n(input.evidence_count)??0;
const identityReady=Boolean(input.candidate_key||input.normalized_identity_key||input.parcel_id||input.external_id);
const underwritingStatus=String(input.underwriting_status||u.status||'review').toLowerCase();
const decision=missing.length||!identityReady||evidenceCount<1?'needs_data':(underwritingStatus==='rejected'||underwritingStatus==='declined'?'not_approved':(mao!==null?'offer_ready':'needs_data'));
const offerReady=decision==='offer_ready';
return [{json:{...input,acquisition_decision:{decision,offer_ready:offerReady,mao,mao_method:providedMao!==null?'provided':(mao!==null?'arv_x_mao_percentage_minus_costs':'unavailable'),inputs:{arv,repairs,holding,closing,assignment,mao_percentage:maoPct},missing_fields:missing,identity_ready:identityReady,evidence_count:evidenceCount,underwriting_status:underwritingStatus,disposition_readiness:offerReady?'ready_for_offer_review':'not_ready'},crm_stage:offerReady?'offer_ready':(decision==='not_approved'?'underwriting_rejected':'underwriting_review')}}];
